/bin/bash -lc "python3 - <<'PY'
from tally import allocate, duration, fields, intervals, ledger, schedule
from fractions import Fraction
from datetime import datetime, timedelta
from time import perf_counter
import random

assert allocate.split(-100, [1,1,1]) == [-34,-33,-33]
assert allocate.split(7, [0, Fraction(1, 3), Fraction(2, 3)]) == [0,2,5]
assert allocate.split(10**30 + 1, [1,1]) == [5*10**29+1, 5*10**29]
assert allocate.format_amount(-5) == '-"'$0.05'"'
for weights in ([], [0,0], [-1,2]):
    try: allocate.split(10, weights)
    except ValueError: pass
    else: raise AssertionError(weights)
assert duration.parse(' 2H 5m 0S ') == 7500
for text in ('', '1h junk', '1m1h', '1h1h', '1.5h', '-1h', '1 h', 'h', '1s2m'):
    try: duration.parse(text)
    except ValueError: pass
    else: raise AssertionError(text)
for n in range(10000): assert duration.parse(duration.format_duration(n)) == n
assert fields.parse_fields(' , a=\" x,= \"\"y\"\" \",, b=,') == {'a':' x,= \"y\" ', 'b':''}
for text in ('a=1,a=2', '=1', 'a', 'a=\"oops', 'a=\"x\"junk', 'a=\"x\"y\"'):
    try: fields.parse_fields(text)
    except ValueError: pass
    else: raise AssertionError(text)
assert intervals.merge([(4,6),(0,3),(2,5),(9,9)]) == [(0,6)]
assert intervals.free_slots([(-3,2),(8,20)],0,10) == [(2,8)]
assert intervals.total_covered([(3,6),(1,4)]) == 5
assert ledger.bill([('Ann','0s'), ('Bob','0s')], 123) == [('Ann',0), ('Bob',0)]
assert ledger.bill([(' A ','1s'), ('a','1s')], 1800) == [('A',1)]
assert ledger.bill([('A','1s')], 1800) == [('A',0)]
assert ledger.bill([('A','3s')], 1800) == [('A',2)]

invalid = ['','@bad','* * * *','* * * * * *','60 * * * *','* 24 * * *','* * 0 * *','* * * 13 *','* * * * 8','* * * * MONL','* * * * 1#0','* * * * 1#6','*/0 * * * *','* 22-2 * * *','* * * * 7-0','* * * * 1#2/2','* * L/2 * *','* * * * ?/2','* * ?,1 * *','? * * * *','* * * * ,1','* * * * 1,','* * * JAN/FEB *','+1 * * * *','* * * * SUN#2','* * * * 1/','* * * * 1//2','* * * * **','* * * * 1.0','*\\n* * * *']
for expr in invalid:
    for fn in (schedule.matches, schedule.next_run):
        try: fn(expr, None)
        except ValueError: pass
        else: raise AssertionError((fn,expr))
checks = [('0 0 L * ?', datetime(2024,2,29), True),('0 0 L * ?',datetime(2023,2,28),True), ('0 0 * * 5L',datetime(2026,5,29),True), ('0 0 * * 5L',datetime(2026,5,22),False), ('0 0 * * 1#2',datetime(2026,5,11),True), ('0 0 * * 01#02',datetime(2026,5,11),True), ('0 0 31 * MON',datetime(2026,5,4),True), ('0 0 31 * MON',datetime(2026,5,5),False), ('0 0 */2 * MON',datetime(2026,5,5),True),('0 0 */2 * MON',datetime(2026,5,4),True),('0 0 * * 6-7',datetime(2026,5,3),True), ('0 0 * * 7',datetime(2026,5,3),True)]
for expr, date, expected in checks: assert schedule.matches(expr,date) == expected, (expr,date)
assert schedule.next_run('0 0 29 FEB *', datetime(2025,3,1)) == datetime(2028,2,29)
assert schedule.next_run('* * * * *', datetime(2026,5,4,10,0,30)) == datetime(2026,5,4,10,1)
assert schedule.next_run('* * * * *', datetime.max) is None
assert schedule.next_run('@yearly',datetime(9999,2,1)) is None
for expr in ('0 0 31 FEB *','0 0 30 FEB ?', '0 0 31 APR,JUN,SEP,NOV *'):
    start=perf_counter()
    assert schedule.next_run(expr,datetime(2026,1,1)) is None
    elapsed=perf_counter()-start
    assert elapsed < .1, elapsed
    print('Impossible schedule search:', round(elapsed*1000,2), 'ms')

# Compare next_run with minute scanning for a variety of day rules and ranges.
rng=random.Random(15)
expressions=['*/17 */3 * * *','3,29,50 0,12,23 * * MON-FRI','5/20 * 1,15 * SUN','*/10 * */2 * MON','* * L * *','0,20,40 * * * 1#2,5L','* * 29 FEB *','*/11 * ? JAN-MAR 6-7/2']
for expr in expressions:
    for _ in range(4):
        after=datetime(2024,rng.randrange(1,4),rng.randrange(1,27),rng.randrange(24),rng.randrange(60),rng.randrange(60))
        result=schedule.next_run(expr,after)
        assert result is not None and result > after and schedule.matches(expr,result), (expr,result)
        cursor=after.replace(second=0,microsecond=0)+timedelta(minutes=1)
        # Test shorter windows exhaustively, and sample all days before distant results.
        if result-cursor < timedelta(days=2):
            while cursor < result:
                assert not schedule.matches(expr,cursor),(expr,cursor,result)
                cursor+=timedelta(minutes=1)
        else:
            cursor=cursor.replace(hour=0,minute=0)
            while cursor.date()<result.date():
                assert not schedule._day_matches(schedule._parse(expr),cursor) or cursor.month not in schedule._parse(expr)[3].values,(expr,cursor,result)
                cursor+=timedelta(days=1)
print('Additional behavioral checks passed.')
PY"

